using Godot;
using System;
using System.Collections.Generic;
using GArray = Godot.Collections.Array;
using Settings = Godot.Collections.Dictionary;

public partial class AudioDocumentOperations
{
    public bool number_in(Variant value,double low,double high)=>value.VariantType is Variant.Type.Int or Variant.Type.Float&&double.IsFinite(value.AsDouble())&&value.AsDouble()>=low&&value.AsDouble()<=high;
    private void ValidateAutomation(Variant automation,string label,List<string> errors)
    {
        if(automation.VariantType!=Variant.Type.Dictionary){errors.Add(label+" automation must be a dictionary.");return;}
        foreach(var raw in automation.AsGodotDictionary().Values)
        {
            if(raw.VariantType!=Variant.Type.Array){errors.Add(label+" automation points must be an array.");continue;}var points=raw.AsGodotArray();if(points.Count>10000)errors.Add(label+" automation has more than 10000 points per curve.");
            foreach(var entry in points){if(entry.VariantType!=Variant.Type.Dictionary){errors.Add(label+" contains an invalid automation point.");continue;}var point=entry.AsGodotDictionary();if(!number_in(Get(point,"time",0),0,10000000)||!number_in(Get(point,"value",0),-10000000,10000000))errors.Add(label+" has invalid automation values.");if(Get(point,"curve","linear").AsString() is not "linear" and not "smooth" and not "hold")errors.Add(label+" has an unknown automation curve.");}
        }
    }
    private void ValidateOwner(Settings owner,string label,List<string> errors)
    {
        if(!number_in(Get(owner,"volume_db",0),-120,60)||!number_in(Get(owner,"pan",0),-1,1))errors.Add(label+" has an invalid gain or pan.");ValidateAutomation(Get(owner,"automation",new Settings()),label,errors);var effects=Get(owner,"effects",new GArray());if(effects.VariantType!=Variant.Type.Array){errors.Add(label+" effects must be an array.");return;}var ids=new HashSet<string>();
        foreach(var raw in effects.AsGodotArray())
        {
            if(raw.VariantType!=Variant.Type.Dictionary){errors.Add(label+" contains an invalid effect.");continue;}var effect=raw.AsGodotDictionary();string id=Get(effect,"id","").AsString();if(id.Length==0||!ids.Add(id))errors.Add(label+" contains invalid or duplicate effect identifiers.");var parameters=Get(effect,"parameters",new Settings());if(Get(effect,"type","").AsString().Length==0||parameters.VariantType!=Variant.Type.Dictionary)errors.Add(label+" contains malformed effect parameters.");else foreach(var value in parameters.AsGodotDictionary().Values)if(value.VariantType==Variant.Type.Float&&!double.IsFinite(value.AsDouble()))errors.Add(label+" contains non-finite effect parameters.");ValidateAutomation(Get(effect,"automation",new Settings()),label+" effect",errors);
        }
    }
    public string[] validate_owner(Settings owner,string label){var errors=new List<string>();ValidateOwner(owner,label,errors);return errors.ToArray();}
    public string[] validate_automation(Variant automation,string label){var errors=new List<string>();ValidateAutomation(automation,label,errors);return errors.ToArray();}
    public string[] validate(GodotObject o)
    {
        var errors=new List<string>();using var conductor=new AudioConductorOperations();double tempo=o.Get("tempo").AsDouble(),baseTempo=o.Get("note_base_tempo").AsDouble();var signature=o.Get("time_signature").AsVector2I();var baseMeter=o.Get("note_base_meter").AsVector2I();string conductorError=conductor.validate(tempo,signature,o.Get("tempo_points"),o.Get("meter_points"));if(conductorError.Length>0)errors.Add(conductorError);if(baseTempo!=0&&!number_in(baseTempo,20,400))errors.Add("Invalid fallback note-source tempo.");if(baseMeter!=Vector2I.Zero&&!conductor.meter(baseMeter.X,baseMeter.Y))errors.Add("Invalid fallback note-source meter.");
        var binding=o.Get("scene_binding").AsGodotDictionary();if(binding.Count>0){if(binding.Count>4||!number_in(Get(binding,"version",0),1,1))errors.Add("Unsupported scene association.");foreach(string field in new[]{"scene_uid","scene_path","actor_id"}){var value=Get(binding,field,"");if(value.VariantType!=Variant.Type.String||value.AsString().Length>(field=="scene_path"?4096:128))errors.Add("Invalid scene association field.");}if(Get(binding,"scene_uid","").AsString().Length==0)errors.Add("Scene association identity is missing.");}
        string midiError=midi_timing_error(o,new GArray(),"",default);if(midiError.Length>0)errors.Add(midiError);long version=o.Get("version").AsInt64();var actors=Actors(o);var clips=Clips(o);var tracks=Tracks(o);if(version<1||version>1)errors.Add("Unsupported audio document version.");if(actors.Count!=clips.Count)errors.Add("Audio actors and clips have different lengths.");if(!double.IsFinite(tempo)||tempo<20||tempo>400)errors.Add("Tempo must be between 20 and 400 BPM.");if(signature.X<1||signature.X>32||signature.Y is not 1 and not 2 and not 4 and not 8 and not 16 and not 32)errors.Add("Invalid time signature.");int key=o.Get("key").AsInt32();if(key<0||key>11)errors.Add("Invalid musical key.");double loopStart=o.Get("loop_start").AsDouble(),loopEnd=o.Get("loop_end").AsDouble();if(!double.IsFinite(loopStart)||!double.IsFinite(loopEnd)||loopStart<0||loopEnd<loopStart)errors.Add("Invalid loop range.");ValidateOwner(o.Get("master").AsGodotDictionary(),"Master",errors);
        var ids=new HashSet<string>();var routes=new Dictionary<string,List<string>>();
        foreach(var raw in tracks)
        {
            var track=raw.AsGodotDictionary();string id=Get(track,"id","").AsString();bool freshId=ids.Add(id);if(id.Length==0||!freshId)errors.Add("Invalid or duplicate track identifier.");ValidateOwner(track,"Track",errors);
            if(track.TryGetValue("automation_target",out var target)){if(target.VariantType!=Variant.Type.Dictionary)errors.Add("Automation lane target must be a dictionary.");else{var t=target.AsGodotDictionary();if(t.Count>0){if(Get(t,"owner_kind","").AsString() is not "clip" and not "track" and not "master")errors.Add("Invalid automation lane owner kind.");foreach(string field in new[]{"owner_id","effect_id","parameter"}){var value=Get(t,field,"");if(value.VariantType!=Variant.Type.String||value.AsString().Length>512)errors.Add("Invalid automation lane target field.");}if(Get(t,"parameter","").AsString().Length==0)errors.Add("Automation lane parameter is missing.");}}}
            var targets=new List<string>();string output=Get(track,"output","").AsString();if(output.Length>0)targets.Add(output);var sends=Get(track,"sends",new GArray());if(sends.VariantType!=Variant.Type.Array)errors.Add("Track sends must be an array.");else foreach(var sendRaw in sends.AsGodotArray()){if(sendRaw.VariantType!=Variant.Type.Dictionary){errors.Add("Invalid track send.");continue;}var send=sendRaw.AsGodotDictionary();string destination=Get(send,"target","").AsString();if(destination.Length==0)errors.Add("A track send target is missing.");else targets.Add(destination);if(!number_in(Get(send,"volume_db",-12.0),-120,24))errors.Add("Invalid send level.");}routes[id]=targets;
        }
        var incoming=new Dictionary<string,int>();foreach(string id in ids)incoming[id]=0;foreach(var route in routes)foreach(string target in route.Value){if(!ids.Contains(target))errors.Add("A track output or send target is missing.");else ++incoming[target];}var ready=new Stack<string>();foreach(var pair in incoming)if(pair.Value==0)ready.Push(pair.Key);int visited=0;while(ready.Count>0){string id=ready.Pop();++visited;if(!routes.TryGetValue(id,out var targets))continue;foreach(string target in targets){if(!incoming.ContainsKey(target))continue;if(--incoming[target]==0)ready.Push(target);}}if(visited!=ids.Count)errors.Add("Track output or send routing contains a feedback cycle.");
        var clipIds=new HashSet<string>();var actorIds=new HashSet<string>();using var linked=new AudioLinkedPatternOperations();
        for(int i=0;i<Math.Min(actors.Count,clips.Count);++i)
        {
            var clip=clips[i].AsGodotObject();var actor=actors[i].AsGodotObject();if(clip==null||actor==null){errors.Add("An audio clip or source actor is missing.");continue;}string clipId=clip.Get("id").AsString(),actorId=actor.Get("id").AsString();if(!clipIds.Add(clipId)||clipId.Length==0)errors.Add("Invalid or duplicate clip identifier.");if(!actorIds.Add(actorId)||actorId.Length==0)errors.Add("Invalid or duplicate audio actor identifier.");if(clip.Get("actor_id").AsString()!=actorId)errors.Add("Clip source reference does not match its actor.");var values=actor.Get("values").AsGodotDictionary();if(!ids.Contains(Get(values,"track_id","").AsString()))errors.Add("Clip track is missing.");double start=clip.Get("start_time").AsDouble(),duration=clip.Get("duration").AsDouble(),offset=clip.Get("source_offset").AsDouble(),speed=clip.Get("playback_speed").AsDouble();if(!double.IsFinite(start)||!double.IsFinite(duration)||start<0||duration<=0)errors.Add("Clip has an invalid time range.");if(!double.IsFinite(offset)||offset<0)errors.Add("Clip has an invalid source offset.");if(!number_in(Get(values,"pitch",1.0),.05,16))errors.Add("Invalid clip pitch.");if(!double.IsFinite(speed)||speed<.05||speed>16)errors.Add("Invalid clip speed.");foreach(string field in new[]{"fade_in","fade_out"})if(!number_in(Get(values,field,0),0,86400))errors.Add("Invalid clip fade.");ValidateOwner(values,"Clip",errors);
            if(values.ContainsKey(new StringName("drum_instances"))||values.ContainsKey(new StringName("drum_patterns"))){string error=linked.validate(Get(values,"drum_patterns",new Settings()),Get(values,"drum_instances",new GArray()));if(error.Length>0)errors.Add(error);}var source=Get(values,"audio");if(source.VariantType!=Variant.Type.Nil&&source.VariantType!=Variant.Type.String&&!(source.VariantType==Variant.Type.Object&&source.AsGodotObject() is AudioStream))errors.Add("Unsupported audio source reference.");var notes=Get(values,"notes",new GArray());if(notes.VariantType!=Variant.Type.Array)errors.Add("Pattern notes must be an array.");else foreach(var raw in notes.AsGodotArray()){if(raw.VariantType!=Variant.Type.Dictionary){errors.Add("Invalid pattern note.");continue;}var note=raw.AsGodotDictionary();if(!number_in(Get(note,"start",0),0,10000000)||!number_in(Get(note,"duration",.25),.000001,10000000)||!number_in(Get(note,"pitch",60),0,127)||!number_in(Get(note,"velocity",.8),0,1))errors.Add("Invalid note time, pitch or velocity.");}
        }
        foreach(var raw in o.Get("markers").AsGodotArray())if(!number_in(Get(raw.AsGodotDictionary(),"time",0),0,10000000))errors.Add("Invalid cue marker time.");foreach(var raw in o.Get("sections").AsGodotArray()){var section=raw.AsGodotDictionary();if(!number_in(Get(section,"start",0),0,10000000)||!number_in(Get(section,"duration",1),.000001,10000000))errors.Add("Invalid arrangement section.");}return errors.ToArray();
    }
}
